// Imported SVG asset catalog for the Graphic Designer.
// Each entry uses the same adaptable SVG object template as the curated library.

const svgTemplate = (svgPath, width, height, id, name) => ({
  type: 'svgSymbol', svgPath, width, height, rotation: 0, opacity: 1,
  symbolTint: null, symbolTintStrength: 1, symbolBrightness: 1, preserveAspect: true,
  boundTag: null, tooltip: '', isVisible: true, libraryVersion: 'industrial-original-v2',
  symbolId: id, objectName: name,
});

const symbol = (id, category, subcategory, name, description, keywords, icon, svgPath, width, height) => ({
  id, category, subcategory, name, description, keywords, icon, thumbnail: svgPath,
  template: svgTemplate(svgPath, width, height, id, name),
});

